[asy]
import three;
import solids;

size(200);
currentprojection = perspective(6,3,2);
currentlight = (1,0,1);
real theta = 120;

draw((-2,0,0)--(2,0,0));
draw((0,-2,0)--(0,2,0));
draw(surface((1,1,0.5)--(1,-1,0.5)--(-1,-1,0.5)--(-1,1,0.5)--cycle),gray(0.99));
draw((0,0,-2)--(0,0,0.2));
draw((0,0,0.5)--(0,0,2));

label("$x$", (2,0,0), SW);
label("$y$", (0,2,0), E);
label("$z$", (0,0,2), N);
label("$z = c$", (-1,1,0.5), E);
[/asy]

